package com.tekwatt.ocpp.websocket;import java.util.Map;import org.springframework.beans.factory.annotation.Value;import org.springframework.http.server.*;import org.springframework.stereotype.Component;import org.springframework.web.socket.*;import org.springframework.web.socket.server.HandshakeInterceptor;import org.springframework.web.util.UriTemplate;
@Component public class OcppHandshakeInterceptor implements HandshakeInterceptor{private final String sharedKey;public OcppHandshakeInterceptor(@Value("${tekwatt.ocpp.shared-key:}")String key){sharedKey=key;}public boolean beforeHandshake(ServerHttpRequest req,ServerHttpResponse res,WebSocketHandler h,Map<String,Object>a){String station=new UriTemplate("/ocpp/{stationId}").match(req.getURI().getPath()).get("stationId");if(station==null||station.isBlank())return false;if(!sharedKey.isBlank()&&!sharedKey.equals(req.getHeaders().getFirst("X-OCPP-Key")))return false;a.put("stationId",station);return true;}public void afterHandshake(ServerHttpRequest r,ServerHttpResponse s,WebSocketHandler h,Exception e){}}
